class Akun:
    def __init__(self):
        self.gagal = 0
        self.status = 'aktif'

    def login(self, benar):
        if self.status == 'terkunci':
            return 'ditolak'
        if benar:
            self.gagal = 0
            self.status = 'aktif'
            return 'masuk'
        self.gagal += 1
        self.status = 'terkunci' if self.gagal >= 3 else 'peringatan'
        return self.status

def tes_tiga_gagal_mengunci():
    a = Akun()
    hasil = [a.login(False) for _ in range(3)]
    assert hasil == ['peringatan', 'peringatan', 'terkunci']

def tes_terkunci_menolak_sandi_benar():
    a = Akun()
    for _ in range(3):
        a.login(False)
    assert a.login(True) == 'ditolak'

def tes_berhasil_mereset_hitungan():
    a = Akun()
    a.login(False); a.login(False); a.login(True)
    assert a.login(False) == 'peringatan', f'hitungan gagal {a.gagal}'

jalankan(tes_tiga_gagal_mengunci, tes_terkunci_menolak_sandi_benar, tes_berhasil_mereset_hitungan)

