class Keranjang:
    def __init__(self):
        self.isi = {}
    def tambah(self, nama, harga, qty=1):
        if qty < 1:
            raise ValueError('qty minimal 1')
        lama = self.isi.get(nama, (harga, 0))[1]
        self.isi[nama] = (harga, lama + qty)
    def total(self):
        return sum(h * q for h, q in self.isi.values())

def tes_tambah_produk_sama_menjumlah_qty():
    k = Keranjang()
    k.tambah('Kopi', 85000)
    k.tambah('Kopi', 85000, 2)
    assert k.isi['Kopi'] == (85000, 3)

def tes_total_dua_produk():
    k = Keranjang()
    k.tambah('Kopi', 85000)
    k.tambah('Gula Aren', 25000, 2)
    assert k.total() == 135000

def tes_qty_nol_ditolak():
    k = Keranjang()
    try:
        k.tambah('Kopi', 85000, 0)
        assert False, 'harus error'
    except ValueError:
        pass
    assert k.total() == 0

jalankan(tes_tambah_produk_sama_menjumlah_qty, tes_total_dua_produk, tes_qty_nol_ditolak)

import unittest

def email_valid(e):
    nama, _, domain = e.partition('@')
    return bool(nama) and '.' in domain and ' ' not in e

class TesEmail(unittest.TestCase):
    def test_valid(self):
        for e in ['rina@contoh.id', 'budi.s@kantor.co.id']:
            with self.subTest(email=e):
                self.assertTrue(email_valid(e))

    def test_tidak_valid(self):
        for e in ['rina', 'rina@', '@contoh.id', 'rina @contoh.id', 'rina@contoh']:
            with self.subTest(email=e):
                self.assertFalse(email_valid(e))

hasil = unittest.TestResult()
unittest.defaultTestLoader.loadTestsFromTestCase(TesEmail).run(hasil)
print(f'{hasil.testsRun} tes, {len(hasil.failures)} gagal')

import json

SKEMA = {'id': int, 'nama': str, 'harga': int, 'stok': int, 'kategori': str}

def cek_skema(data, skema):
    salah = []
    for kunci, tipe in skema.items():
        if kunci not in data:
            salah.append(f'{kunci} hilang')
        elif not isinstance(data[kunci], tipe):
            salah.append(f'{kunci} bertipe {type(data[kunci]).__name__}, harap {tipe.__name__}')
    salah += [f'{k} tidak dikenal' for k in data if k not in skema]
    return salah or ['sesuai']

v1 = json.loads('{"id": 12, "nama": "Kopi Gayo", "harga": 85000, "stok": 14, "kategori": "kopi"}')
v2 = json.loads('{"id": 12, "nama": "Kopi Gayo", "harga": "85000", "stok": 14, "kat": "kopi"}')
print('v1:', cek_skema(v1, SKEMA))
print('v2:', cek_skema(v2, SKEMA))

