import time

def tunggu_sampai(kondisi, batas=2.0, jeda=0.05):
    mulai = time.monotonic()
    while time.monotonic() - mulai < batas:
        if kondisi():
            return round(time.monotonic() - mulai, 1)
        time.sleep(jeda)
    raise AssertionError(f'kondisi tidak terpenuhi dalam {batas} detik')

siap_pada = time.monotonic() + 0.3          # status pembayaran berubah setelah 0,3 detik
status = lambda: 'Berhasil' if time.monotonic() >= siap_pada else 'Diproses'

lama = tunggu_sampai(lambda: status() == 'Berhasil')
print('selesai menunggu dalam < 1 detik:', lama < 1, '(sleep(5) selalu 5 detik)')
try:
    tunggu_sampai(lambda: status() == 'Dibatalkan', batas=0.2)
except AssertionError as e:
    print('GAGAL:', e)

from datetime import datetime, timedelta

class OTP:
    def __init__(self, kode, jam):
        self.jam = jam
        self.kode, self.dibuat = kode, jam()
    def cocok(self, kode):
        return kode == self.kode and self.jam() - self.dibuat <= timedelta(minutes=5)

class JamPalsu:
    def __init__(self, t): self.t = t
    def __call__(self): return self.t
    def maju(self, **kw): self.t += timedelta(**kw)

jam = JamPalsu(datetime(2026, 12, 12, 9, 0))
otp = OTP('4821', jam)
jam.maju(minutes=4, seconds=59); print('4:59 ->', otp.cocok('4821'))
jam.maju(seconds=1);             print('5:00 ->', otp.cocok('4821'))
jam.maju(seconds=1);             print('5:01 ->', otp.cocok('4821'))

